/**
 * Verify that the splitWindowsUsernameFromDomain() method correctly strips Windows
 * domains from provided usernames that include them, and does not modify
 * usernames that do not have Windows domains.
 */
@Test
public void testSplitWindowsUsernameFromDomain() {
    WindowsUsername usernameAndDomain;
    // If no Windows domain is present in the provided field, the username should
    // contain the entire field, and no domain should be returned
    usernameAndDomain = WindowsUsername.splitWindowsUsernameFromDomain("bob");
    assertEquals(usernameAndDomain.getUsername(), "bob");
    assertFalse(usernameAndDomain.hasDomain());
    // It should parse down-level logon name style domains
    usernameAndDomain = WindowsUsername.splitWindowsUsernameFromDomain("localhost\\bob");
    assertEquals("bob", usernameAndDomain.getUsername(), "bob");
    assertTrue(usernameAndDomain.hasDomain());
    assertEquals("localhost", usernameAndDomain.getDomain());
    // It should parse user principal name style domains
    usernameAndDomain = WindowsUsername.splitWindowsUsernameFromDomain("bob@localhost");
    assertEquals("bob", usernameAndDomain.getUsername(), "bob");
    assertTrue(usernameAndDomain.hasDomain());
    assertEquals("localhost", usernameAndDomain.getDomain());
    // It should not match if there are an invalid number of separators
    List<String> invalidSeparators = Arrays.asList("bob@local@host", "local\\host\\bob", "bob\\local@host", "local@host\\bob");
    invalidSeparators.stream().forEach(invalidSeparator -> {
        // An invalid number of separators means that the parse failed -
        // there should be no detected domain, and the entire field value
        // should be returned as the username
        WindowsUsername parseOutput = WindowsUsername.splitWindowsUsernameFromDomain(invalidSeparator);
        assertFalse(parseOutput.hasDomain());
        assertEquals(invalidSeparator, parseOutput.getUsername());
    });
}

/**
 * Test of ReaderGuacamoleReader parsing.
 *
 * @throws GuacamoleException If a parse error occurs while parsing the
 *                            known-good test string.
 */
@Test
public void testReader() throws GuacamoleException {
    // Test string
    final String test = "1.a,2.bc,3.def,10.helloworld;4.test,5.test2;0.;3.foo;";
    GuacamoleReader reader = new ReaderGuacamoleReader(new StringReader(test));
    GuacamoleInstruction instruction;
    // Validate first test instruction
    instruction = reader.readInstruction();
    assertNotNull(instruction);
    assertEquals(3, instruction.getArgs().size());
    assertEquals("a", instruction.getOpcode());
    assertEquals("bc", instruction.getArgs().get(0));
    assertEquals("def", instruction.getArgs().get(1));
    assertEquals("helloworld", instruction.getArgs().get(2));
    // Validate second test instruction
    instruction = reader.readInstruction();
    assertNotNull(instruction);
    assertEquals(1, instruction.getArgs().size());
    assertEquals("test", instruction.getOpcode());
    assertEquals("test2", instruction.getArgs().get(0));
    // Validate third test instruction
    instruction = reader.readInstruction();
    assertNotNull(instruction);
    assertEquals(0, instruction.getArgs().size());
    assertEquals("", instruction.getOpcode());
    // Validate fourth test instruction
    instruction = reader.readInstruction();
    assertNotNull(instruction);
    assertEquals(0, instruction.getArgs().size());
    assertEquals("foo", instruction.getOpcode());
    // There should be no more instructions
    instruction = reader.readInstruction();
    assertNull(instruction);
}

@Test
public void testFilter() throws Exception {
    // Test string
    final String test = "3.yes,1.A;2.no,1.B;3.yes,1.C;3.yes,1.D;4.nope,1.E;";
    GuacamoleReader reader = new FilteredGuacamoleReader(new ReaderGuacamoleReader(new StringReader(test)), new TestFilter());
    GuacamoleInstruction instruction;
    // Validate first instruction
    instruction = reader.readInstruction();
    assertNotNull(instruction);
    assertEquals("yes", instruction.getOpcode());
    assertEquals(1, instruction.getArgs().size());
    assertEquals("A", instruction.getArgs().get(0));
    // Validate second instruction
    instruction = reader.readInstruction();
    assertNotNull(instruction);
    assertEquals("yes", instruction.getOpcode());
    assertEquals(1, instruction.getArgs().size());
    assertEquals("C", instruction.getArgs().get(0));
    // Validate third instruction
    instruction = reader.readInstruction();
    assertNotNull(instruction);
    assertEquals("yes", instruction.getOpcode());
    assertEquals(1, instruction.getArgs().size());
    assertEquals("D", instruction.getArgs().get(0));
    // Should be done now
    instruction = reader.readInstruction();
    assertNull(instruction);
}

@Test
public void testFilter() throws Exception {
    StringWriter stringWriter = new StringWriter();
    GuacamoleWriter writer = new FilteredGuacamoleWriter(new WriterGuacamoleWriter(stringWriter), new TestFilter());
    // Write a few chunks of complete instructions
    writer.write("3.yes,1.A;2.no,1.B;3.yes,1.C;3.yes,1.D;4.nope,1.E;".toCharArray());
    writer.write("1.n,3.abc;3.yes,5.hello;2.no,4.test;3.yes,5.world;".toCharArray());
    // Validate filtered results
    assertEquals("3.yes,1.A;3.yes,1.C;3.yes,1.D;3.yes,5.hello;3.yes,5.world;", stringWriter.toString());
}

