/**
 * Verifies that token replacement via filter() functions as specified.
 */
@Test
public void testFilter() {
    // Create token filter
    TokenFilter tokenFilter = new TokenFilter();
    tokenFilter.setToken("TOKEN_A", "value-of-a");
    tokenFilter.setToken("TOKEN_B", "value-of-b");
    tokenFilter.setToken("TOKEN_C", "Value-of-C");
    // Test basic substitution and escaping
    assertEquals("$${NOPE}hellovalue-of-aworldvalue-of-b${NOT_A_TOKEN}", tokenFilter.filter("$$${NOPE}hello${TOKEN_A}world${TOKEN_B}$${NOT_A_TOKEN}"));
    // Unknown tokens must be interpreted as literals
    assertEquals("${NOPE}hellovalue-of-aworld${TOKEN_D}", tokenFilter.filter("${NOPE}hello${TOKEN_A}world${TOKEN_D}"));
    assertEquals("Value-of-C", tokenFilter.filter("${TOKEN_C}"));
    assertEquals("value-of-c", tokenFilter.filter("${TOKEN_C:LOWER}"));
    assertEquals("VALUE-OF-C", tokenFilter.filter("${TOKEN_C:UPPER}"));
}

/**
 * Verifies that token replacement via filterValues() functions as
 * specified.
 */
@Test
public void testFilterValues() {
    // Create token filter
    TokenFilter tokenFilter = new TokenFilter();
    tokenFilter.setToken("TOKEN_A", "value-of-a");
    tokenFilter.setToken("TOKEN_B", "value-of-b");
    // Create test map
    Map<Integer, String> map = new HashMap<>();
    map.put(1, "$$${NOPE}hello${TOKEN_A}world${TOKEN_B}$${NOT_A_TOKEN}");
    map.put(2, "${NOPE}hello${TOKEN_A}world${TOKEN_C}");
    map.put(3, null);
    // Filter map values
    tokenFilter.filterValues(map);
    // Filter should not affect size of map
    assertEquals(3, map.size());
    // Filtered value 1
    assertEquals("$${NOPE}hellovalue-of-aworldvalue-of-b${NOT_A_TOKEN}", map.get(1));
    // Filtered value 2
    assertEquals("${NOPE}hellovalue-of-aworld${TOKEN_C}", map.get(2));
    // Null values are not filtered
    assertNull(map.get(3));
}

/**
 * Verifies that TokenName.canonicalize() generates token names as
 * specified, regardless of the format of the provided string.
 */
@Test
public void testCanonicalize() {
    assertEquals("A", TokenName.canonicalize("a"));
    assertEquals("B", TokenName.canonicalize("b"));
    assertEquals("1", TokenName.canonicalize("1"));
    assertEquals("SOME_URL", TokenName.canonicalize("someURL"));
    assertEquals("LOWERCASE_WITH_DASHES", TokenName.canonicalize("lowercase-with-dashes"));
    assertEquals("HEADLESS_CAMEL_CASE", TokenName.canonicalize("headlessCamelCase"));
    assertEquals("CAMEL_CASE", TokenName.canonicalize("CamelCase"));
    assertEquals("CAMEL_CASE", TokenName.canonicalize("CamelCase"));
    assertEquals("LOWERCASE_WITH_UNDERSCORES", TokenName.canonicalize("lowercase_with_underscores"));
    assertEquals("UPPERCASE_WITH_UNDERSCORES", TokenName.canonicalize("UPPERCASE_WITH_UNDERSCORES"));
    assertEquals("A_VERY_INCONSISTENT_MIX_OF_ALL_STYLES", TokenName.canonicalize("aVery-INCONSISTENTMix_ofAllStyles"));
    assertEquals("ABC_123_DEF_456", TokenName.canonicalize("abc123def456"));
    assertEquals("ABC_123_DEF_456", TokenName.canonicalize("ABC123DEF456"));
    assertEquals("WORD_A_WORD_AB_WORD_ABC_WORD", TokenName.canonicalize("WordAWordABWordABCWord"));
    assertEquals("AUTH_ATTRIBUTE", TokenName.canonicalize("Attribute", "AUTH_"));
    assertEquals("auth_SOMETHING", TokenName.canonicalize("Something", "auth_"));
}
